contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 priorDeposit, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Setup: make an initial deposit so balances[msg.sender] is priorDeposit.
        if (priorDeposit > 0) {
            require(address(this).balance >= priorDeposit);
            c.Deposit{value: priorDeposit}();
