        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = (balBefore > type(uint256).max - amount);

        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

